void reverse_string(char *str) {
    if (str == NULL) return;
    char *end = str;
    while (*end) end++;
    if (end == str) return;
    end--;
    while (str < end) {
        char tmp = *str;
        *str++ = *end;
        *end-- = tmp;
    }
}
